// ---------------------------------------------------------------
// FishSilhouetteMask — canonical binary silhouette mask of the fish
// derived from public/fish/template-ikan.png / template-ikan.svg.
//
// Canonical template canvas: 1492 × 1054
// Template outer frame: x=30..1462 (w=1432), y=30..1024 (h=994)
// Fish bounding box: x=266..1225 (w=960), y=220..833 (h=614)
//
// Stored as base64-encoded Uint16Array of alternating run lengths (RLE):
// starts with count of 0s (background), then 1s (fish), etc.
// ---------------------------------------------------------------

export const TEMPLATE_CANONICAL = {
  width: 1492,
  height: 1054,
  frame: {
    x0: 30,
    y0: 30,
    x1: 1462,
    y1: 1024,
    width: 1432,
    height: 994,
    aspect: 1432 / 994, // 1.44064386
  },
  fish: {
    x0: 266,
    y0: 220,
    x1: 1225,
    y1: 833,
    width: 960,
    height: 614,
    aspect: 960 / 614, // 1.5635179
  },
} as const

const MASK_RLE_B64 = ''

let cachedMask: Uint8Array | null = null

/**
 * Returns a 960×614 Uint8Array where 1 = fish, 0 = outside/background.
 * Generated from the official template and cached in memory.
 */
export function getFishSilhouetteMask(): Uint8Array {
  if (cachedMask) return cachedMask
  const bin = atob(MASK_RLE_B64)
  const bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  const runs = new Uint16Array(bytes.buffer)

  const w = TEMPLATE_CANONICAL.fish.width
  const h = TEMPLATE_CANONICAL.fish.height
  const mask = new Uint8Array(w * h)

  let ptr = 0
  let val = 0
  for (let i = 0; i < runs.length; i++) {
    const count = runs[i]
    if (val === 1) {
      mask.fill(1, ptr, ptr + count)
    }
    ptr += count
    val = val === 0 ? 1 : 0
  }

  cachedMask = mask
  return cachedMask
}
